html:
{%
	var esc = frappe.utils.escape_html;
	var num = function (v) { return v === undefined || v === null || v === "" ? "" : format_number(v, null, 2); };
	var day = function (d) { return d ? frappe.datetime.str_to_user(d) : ""; };
	var raw = (report && report.raw_data) || {};
	var summary = raw.report_summary || [];
	/* column labels come from the report itself, already in the user's language */
	var label_of = {};
	var server_columns = raw.columns || [];
	for (var c = 0; c < server_columns.length; c++) {
		if (server_columns[c] && server_columns[c].fieldname) label_of[server_columns[c].fieldname] = server_columns[c].label;
	}
	/* the customer statement always has amounts; the same columns and widths as the supplier A4 statement, with the
	   customer rate and amount in place of the hourly rate and amount */
	var fields = [["label", 25, "text"], ["first_date", 9, "date"], ["last_date", 9, "date"], ["working_days", 6, "int"],
		["hours", 8, "num"], ["customer_rate", 8, "num"], ["customer_amount", 9, "num"], ["additions", 7.5, "num"],
		["deductions", 7.5, "num"], ["net", 8, "num"]];
	/* the print shows every row of the period: projects, equipment, every card, then the grand total */
	var rows = [];
	for (var i = 0; i < original_data.length; i++) {
		if (original_data[i]) rows.push(original_data[i]);
	}
	/* additions and deductions print only when some row has a value; the other columns share the freed width */
	var optional = { additions: 1, deductions: 1 };
	var has_value = function (fieldname) {
		for (var r = 0; r < rows.length; r++) {
			if (parseFloat(rows[r][fieldname]) || 0) return true;
		}
		return false;
	};
	/* FR-118: billable stopped hours print right after the hours only when some row has them */
	if (has_value("stopped_hours")) {
		var with_stopped = [];
		for (var f = 0; f < fields.length; f++) {
			with_stopped.push(fields[f]);
			if (fields[f][0] === "hours") with_stopped.push(["stopped_hours", 7, "num"]);
		}
		fields = with_stopped;
	}
	var shown = [];
	var shown_width = 0;
	for (var f = 0; f < fields.length; f++) {
		if (!optional[fields[f][0]] || has_value(fields[f][0])) {
			shown.push(fields[f]);
			shown_width += fields[f][1];
		}
	}
	fields = [];
	for (var f = 0; f < shown.length; f++) {
		fields.push([shown[f][0], Math.round((shown[f][1] * 9700) / shown_width) / 100, shown[f][2]]);
	}
	/* the totals table spans the amount columns at the end of the rows table */
	var totals_from = "customer_rate";
	var totals_width = 0;
	var in_totals = false;
	for (var f = 0; f < fields.length; f++) {
		if (fields[f][0] === totals_from) in_totals = true;
		if (in_totals) totals_width += fields[f][1];
	}
	totals_width = Math.max(35, Math.min(60, Math.round(totals_width)));
	/* the totals come from the cards of the period (before VAT): the cards net and, when positive, the part not
	   yet invoiced through CARD. Items are picked by their stable "key" only (server labels are translated); the
	   reconciliation and ledger items stay on the screen report. */
	var summary_of = {};
	for (var s = 0; s < summary.length; s++) {
		if (summary[s] && summary[s].key) summary_of[summary[s].key] = summary[s];
	}
	var print_labels = {
		net_cards: __("Cards net for the period"),
		not_invoiced: __("Work done not yet invoiced (before VAT)")
	};
	var print_keys = ["net_cards", "not_invoiced"];
	var totals = [];
	for (var k = 0; k < print_keys.length; k++) {
		var it = summary_of[print_keys[k]];
		if (!it) continue;
		if (print_keys[k] === "not_invoiced" && !((parseFloat(it.value) || 0) > 0)) continue;
		totals.push({ label: print_labels[print_keys[k]] || it.label, value: it.value, datatype: it.datatype });
	}
	/* the period prints as full dates, as the report computes it: first day of the start month to the last
	   day of the end month (the end month and year default to the start ones) */
	var pad2 = function (n) { return (n < 10 ? "0" : "") + n; };
	var period_day = function (m, y, last) {
		m = parseInt(m, 10); y = parseInt(y, 10);
		if (!m || !y) return "";
		var d = last ? new Date(y, m, 0).getDate() : 1;
		return frappe.datetime.str_to_user(y + "-" + pad2(m) + "-" + pad2(d));
	};
	var period_from = period_day(filters.from_month, filters.from_year, false);
	var period_to = period_day(filters.to_month || filters.from_month, filters.to_year || filters.from_year, true);
	var cell = function (row, f) {
		var v = row[f[0]];
		if (f[2] === "date") return day(v);
		if (f[2] === "num") return num(v);
		if (f[2] === "int") return v === undefined || v === null ? "" : esc(String(v));
		if (f[0] === "label" && row.card && row.shift) v = (v || "") + " \u2014 " + __(row.shift);
		return esc(v === undefined || v === null ? "" : String(v));
	};
%}
<style>
	/* colours follow the standard Frappe print style: gray-900 #171717, gray-700 #525252, gray-600 #7c7c7c,
	   gray-100 #f3f3f3, table border #d1d8dd, print-heading border #aaa */
	@page { size: A4 portrait; margin: 10mm; }
	/* font: Noto Sans Arabic (owner 2026-11-09). The installed font (fontconfig, card/fonts.py) comes first, so the
	   server PDF shapes Arabic; the bundled copies under /assets/card/fonts load in a browser that lacks it. */
	@font-face { font-family: "Card Noto Arabic"; src: url("/assets/card/fonts/NotoSansArabic-Regular.ttf"); font-weight: normal; }
	@font-face { font-family: "Card Noto Arabic"; src: url("/assets/card/fonts/NotoSansArabic-Bold.ttf"); font-weight: bold; }
	@font-face { font-family: "Card Noto Sans"; src: url("/assets/card/fonts/NotoSans-Regular.ttf"); font-weight: normal; }
	@font-face { font-family: "Card Noto Sans"; src: url("/assets/card/fonts/NotoSans-Bold.ttf"); font-weight: bold; }
	.ess {
		font-size: 9pt; line-height: 1.45; color: #171717;
		-webkit-print-color-adjust: exact; print-color-adjust: exact;
	}
	/* a site print style may set the font of every print element with !important; the statement keeps its own font:
	   the ".print-format" selectors are more specific than ".print-format *" */
	.ess, .ess *, .print-format .ess, .print-format .ess * {
		font-family: "Noto Sans Arabic", "Card Noto Arabic", "Noto Sans", "Card Noto Sans", Tahoma, sans-serif !important;
	}
	.ess table { width: 100%; border-collapse: collapse; }
	.ess[dir="rtl"] { direction: rtl; text-align: right; }
	.ess[dir="ltr"] { direction: ltr; text-align: left; }
	.ess[dir="rtl"] .ess-totals td.ess-v { text-align: left; }
	.ess[dir="ltr"] .ess-totals td.ess-v { text-align: right; }
	.ess[dir="rtl"] .ess-totals th { text-align: right; }
	.ess[dir="ltr"] .ess-totals th { text-align: left; }
	.ess .ess-co { font-size: 10pt; font-weight: 700; color: #525252; margin: 0 0 2px; }
	.ess .ess-title { border-bottom: 1px solid #aaa; margin: 0 0 10px; padding-bottom: 4px; }
	.ess .ess-title h2 { margin: 0; font-size: 16pt; font-weight: 700; color: #171717; }
	.ess .ess-meta { width: 70%; margin: 0 0 10px; table-layout: fixed; }
	.ess .ess-meta td { border: none; padding: 2px 0; color: #171717; vertical-align: top; }
	.ess .ess-meta td.ess-ml { width: 14%; font-weight: 700; color: #7c7c7c; }
	.ess .ess-rows { table-layout: fixed; border: 1px solid #d1d8dd; }
	.ess .ess-rows th, .ess .ess-rows td {
		padding: 3px 6px; border: 1px solid #d1d8dd; overflow-wrap: anywhere; word-break: break-word; vertical-align: middle;
	}
	.ess .ess-rows th { background: #f3f3f3; color: #525252; font-weight: 700; text-align: center; vertical-align: middle; }
	.ess .ess-rows thead { display: table-header-group; }
	.ess .ess-rows tr { page-break-inside: avoid; break-inside: avoid; }
	/* text follows the page direction; numbers read left to right, right-aligned so the decimals line up;
	   dates, counts and the row number are centred */
	.ess[dir="rtl"] .ess-rows td.ess-t, .ess[dir="rtl"] .ess-meta td, .ess[dir="rtl"] .ess-totals td.ess-k { text-align: right; }
	.ess[dir="ltr"] .ess-rows td.ess-t, .ess[dir="ltr"] .ess-meta td, .ess[dir="ltr"] .ess-totals td.ess-k { text-align: left; }
	.ess .ess-rows td.ess-num { text-align: right; direction: ltr; unicode-bidi: embed; white-space: nowrap; font-variant-numeric: tabular-nums; }
	.ess .ess-rows td.ess-c { text-align: center; direction: ltr; unicode-bidi: embed; white-space: nowrap; }
	.ess .ess-note { font-size: 8pt; color: #7c7c7c; margin: 0 0 6px; }
	.ess .ess-rows tr.ess-group td { background: #fafafa; font-weight: 700; }
	.ess .ess-rows tr.ess-eq td { font-weight: 700; color: #525252; }
	.ess[dir="rtl"] .ess-rows tr.ess-card td.ess-t { padding-right: 16px; }
	.ess[dir="ltr"] .ess-rows tr.ess-card td.ess-t { padding-left: 16px; }
	.ess .ess-rows tr.ess-total td { background: #f3f3f3; font-weight: 700; border-top: 2px solid #999; }
	/* the totals sit right under the last (amount) columns of the rows table, at the end side of the page,
	   as in a standard invoice; 40% = the width of the hourly rate .. net columns */
	.ess .ess-totals { width: 40%; margin-top: 6px; page-break-before: avoid; break-before: avoid; page-break-inside: avoid; break-inside: avoid; }
	.ess[dir="rtl"] .ess-totals { margin-left: 0; margin-right: auto; }
	.ess[dir="ltr"] .ess-totals { margin-left: auto; margin-right: 0; }
	.ess .ess-totals th {
		color: #525252; font-weight: 700; padding: 4px 6px; border-bottom: 1px solid #aaa;
	}
	.ess .ess-totals td { padding: 3px 6px; border-bottom: 1px solid #ededed; }
	.ess .ess-totals td.ess-k { width: 68%; color: #525252; }
	.ess .ess-issued { font-size: 8pt; color: #7c7c7c; text-align: center; margin: 14px 0 0; }
	.ess .ess-totals td.ess-v { direction: ltr; unicode-bidi: embed; font-weight: 700; font-variant-numeric: tabular-nums; }
	.ess .ess-totals tr:last-child td { font-size: 9.5pt; font-weight: 700; color: #171717; border-top: 1px solid #aaa; border-bottom: none; }
	.ess .ess-signs { margin-top: 14px; table-layout: fixed; page-break-inside: avoid; break-inside: avoid; }
	.ess .ess-signs td { border: none; text-align: center; vertical-align: top; padding: 0 12px; font-weight: 700; color: #525252; }
	/* the signatures and the issued-by line stay together, on the page of the totals */
	.ess .ess-end { page-break-before: avoid; break-before: avoid; page-break-inside: avoid; break-inside: avoid; }
	.ess .ess-signs .ess-line { display: block; border-top: 1px solid #999; margin: 22px 15% 4px; }
</style>
<div class="ess" dir="{%= frappe.utils.is_rtl() ? "rtl" : "ltr" %}">
<div class="ess-co">{%= esc(filters.company || "") %}</div>
<div class="ess-title"><h2>{%= __("Equipment Customer Statement") %}</h2></div>
<table class="ess-meta">
	<tr>
		<td class="ess-ml">{%= __("Company") %}</td><td>{%= esc(filters.company || "") %}</td>
		<td class="ess-ml">{%= __("Customer") %}</td><td>{%= esc(filters.customer || "") %}</td>
	</tr>
	<tr>
		<td class="ess-ml">{%= __("Issue date") %}</td><td>{%= frappe.datetime.str_to_user(frappe.datetime.get_today()) %}</td>
		<td class="ess-ml"></td><td></td>
	</tr>
	<tr>
		<td class="ess-ml">{%= __("From") %}</td><td>{%= esc(period_from) %}</td>
		<td class="ess-ml">{%= __("To") %}</td><td>{%= esc(period_to) %}</td>
	</tr>
</table>
{% if (filters.include_draft) { %}<p class="ess-note"><b>{%= __("Includes draft cards") %}</b></p>{% } %}
<table class="ess-rows">
	<thead>
		<tr>
			<th style="width: 3%">#</th>
			{% for (var f = 0; f < fields.length; f++) { %}
			<th style="width: {%= fields[f][1] %}%">{%= esc(label_of[fields[f][0]] || "") %}</th>
			{% } %}
		</tr>
	</thead>
	<tbody>
		{% var n = 0; for (var r = 0; r < rows.length; r++) { var row = rows[r]; var is_total = row.row_id === "TOTAL"; var is_group = !is_total && !row.indent; var is_eq = !is_total && row.indent === 1 && rows.some(function (x) { return x.parent_row === row.row_id; }); var numbered = !is_total && !is_group && !is_eq; if (numbered) { n++; } %}
		<tr class="{%= is_total ? "ess-total" : (is_group ? "ess-group" : (is_eq ? "ess-eq" : "ess-card")) %}">
			<td class="ess-c">{%= numbered ? n : "" %}</td>
			{% for (var f = 0; f < fields.length; f++) { %}
			<td class="{%= fields[f][2] === "num" ? "ess-num" : (fields[f][2] === "int" || fields[f][2] === "date" ? "ess-c" : "ess-t") %}">{%= cell(row, fields[f]) %}</td>
			{% } %}
		</tr>
		{% } %}
	</tbody>
</table>
{% if (totals.length) { %}
<table class="ess-totals" style="width: {%= totals_width %}%">
	<thead><tr><th colspan="2">{%= __("Statement totals") %}</th></tr></thead>
	<tbody>
		{% for (var s = 0; s < totals.length; s++) { var item = totals[s]; %}
		<tr>
			<td class="ess-k">{%= esc(item.label || "") %}</td>
			<td class="ess-v">{%= item.datatype === "Int" ? esc(String(item.value === undefined || item.value === null ? "" : item.value)) : num(item.value) %}</td>
		</tr>
		{% } %}
	</tbody>
</table>
{% } %}
<div class="ess-end">
<table class="ess-signs">
	<tr>
		<td><span class="ess-line"></span>{%= __("Accountant signature") %}</td>
		<td><span class="ess-line"></span>{%= __("Reviewer signature") %}</td>
		<td><span class="ess-line"></span>{%= __("Customer signature") %}</td>
	</tr>
</table>
<p class="ess-issued">{%= esc(__("Issued by the electronic system of {0}", [filters.company || ""])) %}</p>
</div>
</div>
